/** T03 fixed-response controller scenarios: the pure time-scan point with
 * non-empty scan deltas (T03) and the automatic-round collapse point whose
 * single group achieves a task its own subtasks add (T03-collapse), both for
 * both samples. Same session discipline as T02: harness-issued bootstrap,
 * seeded lease and group identities, preview specimens after every
 * begin/stage anchor, model expectations generated by walking the recording.
 *
 * Specimen bodies: a begin anchor shows the point's BASE state under the
 * staged successor time; post-stage anchors show the trace's own final state
 * under the same time (the scan/group is the only delta source, so the
 * committed body is the merged one). The base state for both traces is the
 * shared root body recorded as T02's final state (T03 opens on root_0,
 * T03-collapse on the T02 end) for the matching sample. Every derivation was
 * verified at authoring time for both samples against the recorded digests:
 * base+startTime == the s1 head digest, final+successorTime == the commit
 * head digest.
 *
 * Registered deviation bridge: T03-collapse's group candidates record
 * personalityCoverageIds=['person_c'] — the pre-ruling shape, registered as
 * a known deviation fixture (A's validate asserts the violation on the raw
 * trace). The driver produces the ruled shape (achievements ⇒ world roster),
 * so this scenario normalizes recorded coverage fields to the ruling at
 * derivation and on the corpus requests; the trace file itself is untouched.
 *
 * T03-collapse's task/change/point/group allocation is controller-issued
 * before pointPlan. Identities are adopted from its actual response; only
 * the initial get_context is a harness bootstrap.
 *
 * #5 场景级多阶段（2026-10-26 验收）：两条轨迹的录制候选按规范阶段无损分解
 * 为逐阶段 updates 调用（T03=tasks→personality→sanity；collapse=appearance
 * →tasks→subtasks），阶段边界插入 B 授权的部分应用正文预览标本。合并候选
 * 与录制逐字一致，无需语料适配；崩溃组的 tasks 边界触发前向引用拆分（被
 * 延后的达成不入预览，仅可达部分随边界应用），与驱动器发送前预检逐步镜像。 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { ControllerDriver, initialMemory } from './controller';
import { assembleCandidates, mergeUpdatesStages, timeScanCandidates, triggerSlotKey, type UpdatesCall, type UpdatesStage } from './schedule';
import { buildCorpus, frozenGroupActionsAtStage, ScenarioModelPort, ScenarioTransport, servedBeforeSteps, type Corpus, type DeclaredModelCall, type PreviewSpecimenSpec, type ReadStateSpecimenSpec } from './harness';
import { ProtocolError } from './protocol';
import { equal, instantiate, readTrace } from './trace-runner';
import { advanceTime, type WallTime } from './t02.scenario';
import type { ControlState, EntityDelta, Id, Json, SettlementGroup, WorldContext } from './types';

export type T03TraceName = 'T03' | 'T03-collapse';

export interface T03Scenario {
  driver: ControllerDriver;
  transport: ScenarioTransport;
  model: ScenarioModelPort;
  memory: ReturnType<typeof initialMemory>;
  corpus: Corpus;
  roundId: Id;
  bootstrapStepIds: string[];
  finalStepId: string;
}

/** Updates model output rebuilt from the recorded candidates: one call per
 * canonical stage, entity entries carried verbatim so the driver's merge +
 * assemble round-trips to the recorded request. */
function updatesCallsFromCandidates(candidates: Record<string, unknown>): UpdatesCall[] {
  const sections: [UpdatesStage, string, (value: unknown) => Record<string, unknown>][] = [
    ['position', 'positions', (value) => ({ positionSet: value })],
    ['appearance', 'appearances', (value) => ({ appearanceChanges: value })],
    ['tasks', 'tasksAchieved', (value) => ({ tasksAchieved: value })],
    ['subtasks', 'subtasksAdded', (value) => ({ subtasksAdded: value })],
    ['personality', 'personalities', (value) => ({ personalityChanges: value })],
    ['sanity', 'sanities', (value) => ({ sanitySet: value })],
  ];
  const calls: UpdatesCall[] = [];
  for (const [stage, key, wrap] of sections) {
    const section = candidates[key] as Record<string, unknown> | undefined;
    if (!section || Object.keys(section).length === 0) continue;
    const changes: Record<string, unknown> = {};
    for (const [entity, value] of Object.entries(section)) changes[entity] = wrap(structuredClone(value));
    calls.push({ stage, changes: changes as UpdatesCall['changes'] });
  }
  return calls;
}

/** Coverage fields normalized to the 2026-10-22 ruling (achievements ⇒ world
 * roster, else empty) — a no-op for legally recorded candidates. */
function withRuledCoverage(candidates: Record<string, unknown>, roster: Id[], traceName: T03TraceName): Record<string, unknown> {
  const achieved = Object.values((candidates.tasksAchieved ?? {}) as Record<string, unknown[]>).some((list) => list.length > 0);
  const coverage = achieved ? [...roster] : [];
  const knownDeviation = traceName === 'T03-collapse' && achieved && candidates.groupId != null && equal(candidates.actorIds, ['person_c']) && equal(candidates.personalityCoverageIds, ['person_c']);
  if (!equal(candidates.personalityCoverageIds, coverage) && !knownDeviation) throw new ProtocolError(`[${traceName}] unregistered personality coverage deviation`);
  return { ...candidates, personalityCoverageIds: coverage };
}

export function buildT03Scenario(traceName: T03TraceName, sampleId: string): T03Scenario {
  const raw = JSON.parse(readFileSync(resolve(process.cwd(), `../design/world-protocol/v2/traces/${traceName}.json`), 'utf8'));
  const trace = readTrace(raw);
  const sample = trace.samples.find((s) => s.id === sampleId);
  if (!sample) throw new ProtocolError(`Unknown sample ${sampleId}`);
  const requestOf = new Map<string, Record<string, unknown>>();
  const responseOf = new Map<string, Record<string, unknown>>();
  for (const step of trace.steps) {
    requestOf.set(step.id, instantiate(step.request, sample.values) as Record<string, unknown>);
    responseOf.set(step.id, instantiate(step.response, sample.values) as Record<string, unknown>);
  }
  const steps = trace.steps;
  const stepIndex = new Map(steps.map((s, i) => [s.id as string, i]));

  // The base body comes from the T02 line: both traces open on the shared
  // root world for the matching sample (verified at authoring time against
  // the s1 head digest).
  const rawT02 = JSON.parse(readFileSync(resolve(process.cwd(), '../design/world-protocol/v2/traces/T02.json'), 'utf8'));
  const traceT02 = readTrace(rawT02);
  const sampleT02 = traceT02.samples.find((s) => s.id === sampleId);
  const finalStepT02 = traceT02.steps.find((s) => s.operation === 'get_state');
  if (!sampleT02 || !finalStepT02) throw new ProtocolError(`[${traceName}] base body needs the matching T02 sample's final state`);
  const baseBody = (instantiate(finalStepT02.response, sampleT02.values) as { data: { state: Json } }).data.state;

  const context = responseOf.get('s1') as unknown as { world: WorldContext & { time: WallTime }; control: ControlState };
  if ((context as { work?: unknown }).work != null) throw new ProtocolError(`[${traceName}] bootstrap context unexpectedly carries point work`);
  const roundId = (context.world.activeRoundId ?? context.world.round?.roundId) as Id;
  const order = (context.world.round as { order: Id[] }).order;
  const finalStep = [...steps].reverse().find((s) => s.operation === 'get_state');
  if (!finalStep) throw new ProtocolError(`[${traceName}] no final get_state step`);
  const finalState = (responseOf.get(finalStep.id) as unknown as { data: { state: Json } }).data.state;
  const roster = Object.keys((finalState as { characters: Record<string, unknown> }).characters).sort();

  const begins = steps.filter((s) => s.operation === 'checkpoint_begin_point');
  if (begins.length === 0) throw new ProtocolError(`[${traceName}] no begin points`);
  const beginIndex = begins.map((b) => stepIndex.get(b.id)!);
  const pointAt = (index: number): number => {
    let point = -1;
    for (let i = 0; i < beginIndex.length; i++) if (beginIndex[i] <= index) point = i;
    if (point < 0) throw new ProtocolError(`[${traceName}] step index ${index} precedes the first begin`);
    return point;
  };
  const actorsByPoint = begins.map((_, i) => {
    const end = i + 1 < beginIndex.length ? beginIndex[i + 1] : steps.length;
    const actors = new Set<Id>();
    const actionText = new Map<Id, string>();
    for (const s of steps.slice(beginIndex[i], end)) {
      const req = requestOf.get(s.id)!;
      if (s.operation === 'checkpoint_discover_group') {
        actors.add(req.initiatorId as Id);
        actionText.set(req.initiatorId as Id, req.actionText as string);
      }
      const admit = req.admittedMember as { memberId: Id; actionText?: string | null } | null | undefined;
      if (admit?.memberId) {
        actors.add(admit.memberId);
        actionText.set(admit.memberId, admit.actionText ?? '');
      }
    }
    return { actors: order.filter((id) => actors.has(id)), actionText };
  });
  const commitByPoint = begins.map((_, i) => {
    const end = i + 1 < beginIndex.length ? beginIndex[i + 1] : steps.length;
    const commit = steps.slice(beginIndex[i], end).find((s) => s.operation === 'commit_point');
    if (!commit) throw new ProtocolError(`[${traceName}] point ${i + 1} has no commit`);
    return commit;
  });

  const pointTimes: WallTime[] = [];
  {
    let walk: WallTime = structuredClone(context.world.time);
    for (const b of begins) {
      walk = advanceTime(walk, (requestOf.get(b.id)! as { timeAdvance: { duration: { amount: number } } }).timeAdvance);
      pointTimes.push(structuredClone(walk));
    }
  }

  // 触发键与骰点规则自 #8 起由程序提供（fixture-v1/11 与录制一致），不再
  // 从录制的 create_rolls 反推进模型输出。

  const anchorSteps = steps.filter((s) => ['checkpoint_begin_point', 'checkpoint_stage_unit', 'checkpoint_stage_time_scan'].includes(s.operation));
  const stagedAt = (anchorIndex: number, pointIndex: number): Record<string, unknown>[] => {
    const groups: Record<string, unknown>[] = [];
    for (const s of steps.slice(beginIndex[pointIndex], anchorIndex + 1)) { // inclusive: the anchor's own stage counts
      if (s.operation === 'checkpoint_stage_unit' || s.operation === 'checkpoint_stage_time_scan') {
        groups.push(withRuledCoverage(structuredClone((requestOf.get(s.id)! as { candidates: Record<string, unknown> }).candidates), roster, traceName));
      }
    }
    return groups;
  };
  const specimenSpecs = anchorSteps.map((anchor) => {
    const pointIndex = pointAt(stepIndex.get(anchor.id)!);
    const projection = structuredClone((requestOf.get(commitByPoint[pointIndex].id)! as { point: Record<string, Json> }).point);
    // Before staging, neither the scan nor the group's future deltas
    // belong in the preview projection.
    if (anchor.operation === 'checkpoint_begin_point') projection.entityDeltas = {};
    return {
      label: `b-preview-after-${anchor.id}`,
      anchorIndex: stepIndex.get(anchor.id)!,
      time: pointTimes[pointIndex],
      base: anchor.operation === 'checkpoint_begin_point',
      projection,
      settlementGroups: stagedAt(stepIndex.get(anchor.id)!, pointIndex),
    };
  });
  const specimenBody = (spec: (typeof specimenSpecs)[number]): { workingState: Json; pointProjection: Json; mergedEntityDeltas: Json; settlementGroups: Json[] } => ({
    workingState: { ...(structuredClone(spec.base ? baseBody : finalState) as Record<string, unknown>), time: structuredClone(spec.time) } as unknown as Json,
    pointProjection: structuredClone(spec.projection),
    mergedEntityDeltas: structuredClone(spec.projection.entityDeltas),
    settlementGroups: structuredClone(spec.settlementGroups) as Json[],
  });
  const specimens: PreviewSpecimenSpec[] = specimenSpecs.map((spec) => ({
    afterStepId: steps[spec.anchorIndex].id,
    label: spec.label,
    build: () => specimenBody(spec),
  }));
  const previewStateAt = (index: number): Json => {
    // STRICTLY before: a model call declared at a step runs before that step
    // is consumed, so the anchor AT the index has not served yet.
    let chosen: (typeof specimenSpecs)[number] | null = null;
    for (const spec of specimenSpecs) if (spec.anchorIndex < index) chosen = spec;
    if (!chosen) throw new ProtocolError(`[${traceName}] no preview anchor before step index ${index}`);
    return specimenBody(chosen).workingState;
  };

  // —— #5 场景级多阶段声明（2026-10-26 验收）——录制候选按规范阶段无损分解
  // 为逐阶段模型调用；阶梯在阶段边界经 preview 应用前序候选（部分阶段预览），
  // 最终合并候选与录制逐字一致（transport 的请求全等断言即独立期望）。边界
  // 正文=最终态去掉未应用阶段的内容（部分应用态，时间取点位推进值）；崩溃
  // 组的 tasks 阶段边界触发前向引用拆分——被延后的达成绝不入预览，仅可达
  // 部分随边界再次应用（与驱动器的发送前预检逐步镜像）。轨迹文件不动。
  const stageStep = steps.find((s) => s.operation === (traceName === 'T03' ? 'checkpoint_stage_time_scan' : 'checkpoint_stage_unit'));
  if (!stageStep) throw new ProtocolError(`[${traceName}] no stage step for the split ladder`);
  const stageIndex = stepIndex.get(stageStep.id)!;
  const stageCalls = updatesCallsFromCandidates(withRuledCoverage(requestOf.get(stageStep.id)!.candidates as Record<string, unknown>, roster, traceName));
  if (stageCalls.length < 2) throw new ProtocolError(`[${traceName}] split ladder needs at least two recorded stages`);
  const stageTime = pointTimes[pointAt(stageIndex)];
  const stageGroupId = (requestOf.get(stageStep.id)!.candidates as { groupId?: Id }).groupId ?? null;
  const stageActorIds = (requestOf.get(stageStep.id)!.candidates as { actorIds?: Id[] }).actorIds ?? [];
  const atStageTime = (state: Json): Json => ({ ...(structuredClone(state) as Record<string, unknown>), time: structuredClone(stageTime) }) as unknown as Json;
  // 部分应用正文：最终态去掉未应用内容；理智/位置回落到基态值（录制的最
  // 终态含全部阶段内容，按 id 删除即可精确还原已应用前缀）。
  const stateWithoutCalls = (calls: UpdatesCall[]): Json => {
    const body = structuredClone(finalState) as unknown as { characters: Record<string, Record<string, unknown>> };
    for (const call of calls) {
      for (const [entity, delta] of Object.entries(call.changes)) {
        const character = body.characters[entity];
        if (!character) continue;
        const tasks = character.tasks as Record<string, unknown> | undefined;
        if (tasks) {
          for (const id of delta.tasksAchieved ?? []) delete tasks[id];
          for (const task of delta.subtasksAdded ?? []) delete tasks[task.id];
        }
        if (delta.appearanceChanges?.length) character.appearanceChanges = (character.appearanceChanges as { id: Id }[]).filter((change) => !delta.appearanceChanges!.some((authored) => authored.id === change.id));
        if (delta.personalityChanges?.length) character.personalityChanges = (character.personalityChanges as { id: Id }[]).filter((change) => !delta.personalityChanges!.some((authored) => authored.id === change.id));
        if (delta.sanitySet != null) {
          const base = (baseBody as unknown as { characters: Record<string, { sanity: number }> }).characters[entity];
          if (base) character.sanity = base.sanity;
        }
        if (delta.positionSet) {
          const base = (baseBody as unknown as { characters: Record<string, { position: unknown }> }).characters[entity];
          if (base) character.position = structuredClone(base.position);
        }
      }
    }
    return body as unknown as Json;
  };
  // 逐边界镜像驱动器：合并已声明阶段 → 按上一边界正文的状态过滤前向引用
  // （拆分：仅可达部分入折）→ 在途组与部分应用正文。被延后的达成保留在
  // 原始调用里随最终批次结算，正文推导将其持续视为未应用。
  const boundaryBodies: Json[] = [previewStateAt(stageIndex)];
  const boundaryGroups: SettlementGroup[] = [];
  const deferredByEntity: Record<Id, Id[]> = {};
  for (let k = 1; k < stageCalls.length; k++) {
    const merged = mergeUpdatesStages(stageCalls.slice(0, k));
    const live = boundaryBodies[k - 1] as unknown as { characters: Record<string, { tasks?: Record<string, unknown> }> };
    const valid: Record<Id, EntityDelta> = {};
    for (const [entity, delta] of Object.entries(merged)) {
      const achieved = delta.tasksAchieved ?? [];
      const liveTasks = live.characters[entity]?.tasks ?? {};
      const forward = achieved.filter((id) => liveTasks[id] == null);
      for (const id of forward) (deferredByEntity[entity] ??= []).push(id);
      valid[entity] = forward.length === 0 ? delta : { ...delta, tasksAchieved: achieved.filter((id) => !forward.includes(id)) };
    }
    boundaryGroups.push(stageGroupId == null
      ? timeScanCandidates(valid, roster)
      : assembleCandidates({ groupId: stageGroupId, actorIds: stageActorIds, deltas: valid, roster }));
    const pending = [...stageCalls.slice(k)];
    if (Object.keys(deferredByEntity).length > 0) pending.push({ stage: 'tasks', changes: structuredClone(deferredByEntity) as UpdatesCall['changes'] });
    boundaryBodies.push(atStageTime(stateWithoutCalls(pending)));
  }
  const boundarySpecs: PreviewSpecimenSpec[] = boundaryGroups.map((group, i) => ({
    afterStepId: steps[stageIndex - 1].id,
    label: `b-boundary-${i + 1}-before-${stageStep.id}`,
    build: () => ({
      workingState: atStageTime(boundaryBodies[i + 1]),
      pointProjection: { ...(requestOf.get(commitByPoint[pointAt(stageIndex)].id)! as { point: Record<string, Json> }).point, entityDeltas: {} },
      mergedEntityDeltas: {},
      settlementGroups: [structuredClone(group) as unknown as Json],
    }),
  }));

  const allocateStep = steps.find((s) => s.operation === 'allocate_ids');
  const bootstrapStepIds = ['s1'];

  // 叙事组装（§7.1）：每个 claim 后插入目标读＋前驱读标本（同 T02 模式）。
  const readSpecimens: ReadStateSpecimenSpec[] = [];
  {
    const bootstrapTime = structuredClone(context.world.time) as unknown as Json;
    const bootstrapHead = (context.world as { head: { pointId: Id; stateDigest: string } }).head;
    const atTime = (time: unknown): Json => ({ ...(structuredClone(finalState) as Record<string, unknown>), time: structuredClone(time) }) as unknown as Json;
    for (let i = 0; i < steps.length; i++) {
      if (steps[i].operation !== 'narration_submit') continue;
      const claimStep = steps[i - 1];
      if (!claimStep || claimStep.operation !== 'narration_claim') throw new ProtocolError(`[${traceName}] narration_submit at ${steps[i].id} has no preceding claim`);
      const k = pointAt(stepIndex.get(steps[i].id)!);
      const commitReq = requestOf.get(commitByPoint[k].id)! as { point: { previousPointId: Id | null; timeAdvance: Json; entityDeltas: Json } };
      const head = (responseOf.get(commitByPoint[k].id) as unknown as { world: { head: { pointId: Id; stateDigest: string } } }).world.head;
      const targetState = atTime(pointTimes[k]);
      const beforeState = k > 0 ? atTime(pointTimes[k - 1]) : atTime(bootstrapTime);
      const beforeId = commitReq.point.previousPointId as Id;
      const beforeDigest = k > 0
        ? (responseOf.get(commitByPoint[k - 1].id) as unknown as { world: { head: { stateDigest: string } } }).world.head.stateDigest
        : bootstrapHead.stateDigest;
      readSpecimens.push({
        label: `b-read-target-after-${claimStep.id}`,
        afterStepId: claimStep.id,
        data: { pointId: head.pointId, version: 1, stateDigest: head.stateDigest, previousPointId: commitReq.point.previousPointId, timeAdvance: commitReq.point.timeAdvance, entityDeltas: commitReq.point.entityDeltas, state: targetState } as unknown as Json,
      });
      readSpecimens.push({
        label: `b-read-before-after-${claimStep.id}`,
        afterStepId: `b-read-target-after-${claimStep.id}`,
        data: { pointId: beforeId, version: 0, stateDigest: beforeDigest, previousPointId: null, timeAdvance: null, entityDeltas: {}, state: beforeState } as unknown as Json,
      });
    }
  }

  const corpus = buildCorpus(raw, sampleId, [...specimens, ...boundarySpecs], [...bootstrapStepIds, finalStep.id], [
    { previewStepId: specimenSpecs[specimenSpecs.length - 1].label, expectationStepId: finalStep.id, workingStatePath: '/data/workingState', workingStateDigestPath: '/data/workingStateDigest' },
  ], [], [], readSpecimens);
  // Coverage normalization on the shared requests too: the stage candidates
  // and the commit's settlement groups must carry the ruled shape the driver
  // assembles. The recorded deviation stays in the trace file.
  for (const step of corpus.steps) {
    if (step.sharedStepId == null) continue;
    const req = step.request as Record<string, unknown>;
    if (step.operation === 'checkpoint_stage_unit' || step.operation === 'checkpoint_stage_time_scan') {
      req.candidates = withRuledCoverage(req.candidates as Record<string, unknown>, roster, traceName);
    } else if (step.operation === 'commit_point') {
      req.settlementGroups = ((req.settlementGroups as Record<string, unknown>[]) ?? []).map((group) => withRuledCoverage(group, roster, traceName));
    }
  }

  const declared: DeclaredModelCall[] = [];
  declared.push({ task: 'pointPlan', key: roundId, input: { round: structuredClone(context.world.round) as Json, head: structuredClone(context.world.head) as Json }, output: begins.map((b, i) => {
    const req = requestOf.get(b.id)! as { pointId: Id; kind: Json; timeAdvance: Json };
    return { pointId: req.pointId, kind: req.kind, timeAdvance: structuredClone(req.timeAdvance), actorIds: actorsByPoint[i].actors };
  }) as unknown as Json });
  const recordedActiveInput = (context as unknown as { activeInput: { advanceId: Id; inputId: Id; text: string } | null }).activeInput;
  // §6.1/§7.1：行动输入取调用时刻的 advance（最近服务态＋最后一次 context），
  // results 输入取本组冻结行动——两者均与控制器逐字镜像。
  const servedBefore = servedBeforeSteps(steps, responseOf);
  const declaredAdvance = (stepId: string): Json => {
    const served = servedBefore.get(stepId)!;
    return { inputText: served.activeInput?.text ?? null, intentStatus: served.world!.advance.intentStatus };
  };
  const frozenActions = frozenGroupActionsAtStage(steps, requestOf, responseOf);
  for (const s of steps) {
    const index = stepIndex.get(s.id)!;
    const req = requestOf.get(s.id)!;
    if (s.operation === 'checkpoint_discover_group') {
      declared.push({ task: 'action', key: req.initiatorId as Id, input: { actor: req.initiatorId as Id, advance: declaredAdvance(s.id), workingState: previewStateAt(index) }, output: { kind: 'act', text: req.actionText } as unknown as Json });
    } else if (s.operation === 'checkpoint_extend_group') {
      if (req.targets != null) {
        const targetIds = (req.targets as { targetId: Id }[]).map((t) => ({ targetId: t.targetId }));
        const actionText = actorsByPoint[pointAt(index)].actionText.get(req.sourceId as Id) ?? '';
        declared.push({ task: 'targets', key: req.sourceId as Id, input: { sourceId: req.sourceId as Id, actionText, workingState: previewStateAt(index) }, output: { targets: targetIds } as unknown as Json });
      } else {
        const admit = req.admittedMember as { memberId: Id; actionText: string; rollRefs: { rollId: Id }[] };
        const sourceActionText = actorsByPoint[pointAt(index)].actionText.get(req.sourceId as Id) ?? '';
        declared.push({ task: 'reaction', key: req.sourceId as Id, input: { sourceId: req.sourceId as Id, sourceActionText, memberId: admit.memberId, rollId: admit.rollRefs[0].rollId, workingState: previewStateAt(index) }, output: admit.actionText as unknown as Json });
      }
    } else if (s.operation === 'checkpoint_stage_unit') {
      const candidates = withRuledCoverage(req.candidates as Record<string, unknown>, roster, traceName);
      const groupId = (candidates as { groupId: Id }).groupId;
      declared.push({ task: 'results', key: groupId, input: { groupId, members: structuredClone(frozenActions.get(s.id)!) as unknown as Json, workingState: previewStateAt(index) }, output: structuredClone(req.results) as Json });
      // 拆分阶梯：逐阶段单对象输出（首阶段读阶梯前状态，后序阶段读边界
      // preview 应用前序候选后的部分应用正文——§6.3）。
      if (s.id !== stageStep.id) throw new ProtocolError(`[${traceName}] unexpected stage_unit outside the split ladder`);
      stageCalls.forEach((call, j) => {
        declared.push({
          task: 'updates', key: `${groupId}#${call.stage}`,
          input: { groupId, mode: 'group', stage: call.stage, workingState: j === 0 ? previewStateAt(index) : atStageTime(boundaryBodies[j]) } as unknown as Json,
          output: call as unknown as Json,
        });
      });
    } else if (s.operation === 'checkpoint_stage_time_scan') {
      const candidates = withRuledCoverage(req.candidates as Record<string, unknown>, roster, traceName);
      if (s.id !== stageStep.id) throw new ProtocolError(`[${traceName}] unexpected stage_time_scan outside the split ladder`);
      stageCalls.forEach((call, j) => {
        declared.push({
          task: 'updates', key: `time_scan:${req.pointId as Id}#${call.stage}`,
          input: { mode: 'time_scan', stage: call.stage, workingState: j === 0 ? previewStateAt(index) : atStageTime(boundaryBodies[j]) } as unknown as Json,
          output: call as unknown as Json,
        });
      });
    } else if (s.operation === 'narration_submit') {
      const k = pointAt(index);
      const head = (responseOf.get(commitByPoint[k].id) as unknown as { world: { head: { pointId: Id; stateDigest: string } } }).world.head;
      const commitReq = requestOf.get(commitByPoint[k].id)! as { point: { previousPointId: Id | null; timeAdvance: Json; entityDeltas: Json } };
      const atTimeLit = (time: unknown): Json => ({ ...(structuredClone(finalState) as Record<string, unknown>), time: structuredClone(time) }) as unknown as Json;
      const targetState = atTimeLit(pointTimes[k]);
      const beforeState = k > 0 ? atTimeLit(pointTimes[k - 1]) : atTimeLit(structuredClone(context.world.time));
      const protagonistId = (finalState as { protagonistId: Id }).protagonistId;
      const protagonistName = ((finalState as { initial: { characters: Record<string, { name: string }> } }).initial.characters[protagonistId]).name;
      // 独立字面量（不经 assembleNarrationInput）。
      declared.push({
        task: 'narration', key: head.pointId,
        input: {
          pointId: head.pointId, before: beforeState,
          delta: { timeAdvance: commitReq.point.timeAdvance, entityDeltas: commitReq.point.entityDeltas },
          after: targetState,
          perspective: `主角视角（${protagonistId}「${protagonistName}」）；只表达已结算的世界事实`,
        },
        output: req.text as unknown as Json,
      });
    }
  }

  const ownership = trace.variables.find((v) => v.origin === 'input' && v.kind === 'ownership');
  if (!ownership) throw new ProtocolError(`[${traceName}] no input ownership variable to seed the lease`);
  const memory = initialMemory(`req_${traceName}`, 'browser');
  memory.leaseToken = sample.values[ownership.name] as Id;
  memory.updatesStages = stageCalls.map((call) => call.stage);
  if (allocateStep) {
    const allocation = requestOf.get(allocateStep.id)!;
    memory.roundAllocations[roundId] = { allocationKey: allocation.allocationKey as Id, slots: allocation.slots as NonNullable<typeof memory.allocPlan>['slots'] };
  }
  for (const s of steps) {
    if (!allocateStep && s.operation === 'checkpoint_discover_group') {
      const req = requestOf.get(s.id)! as { initiatorId: Id; groupId: Id };
      memory.ids[`group:${req.initiatorId}`] = req.groupId;
    }
    if (s.operation === 'checkpoint_extend_group') {
      // 程序掌握触发身份（§9.3）：录制值按调度器的稳定组合槽位键绑定进
      // id 表——模型输出不再携带 triggerKey，控制器从已分配映射解析。
      const req = requestOf.get(s.id)! as { groupId: Id; sourceId: Id; targets?: { targetId: Id; triggerKey: Id }[] | null };
      if (Array.isArray(req.targets)) for (const t of req.targets) memory.ids[triggerSlotKey(req.groupId as Id, req.sourceId as Id, t.targetId)] = t.triggerKey;
    }
  }

  const transport = new ScenarioTransport(corpus.steps, traceName);
  const model = new ScenarioModelPort(declared, traceName);
  const driver = new ControllerDriver({ transport, model }, memory, { world: context.world, control: context.control, activeInput: recordedActiveInput }, { retryLimit: 3, identityAliases: { 'group:person_c': 'group' } });
  return { driver, transport, model, memory, corpus, roundId, bootstrapStepIds, finalStepId: finalStep.id };
}

/** Issues the session-open exchanges in recording order. */
export async function openT03Session(scenario: T03Scenario): Promise<void> {
  for (const stepId of scenario.bootstrapStepIds) await scenario.transport.runInspect(stepId);
}
